import assert from 'node:assert/strict';
import fs from 'node:fs';
import { createHash } from 'node:crypto';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
const file='docs/phase-plans/check-phase002-schema-prompt.mjs';
const original=fs.readFileSync(file,'utf8');
const sourceHash=createHash('sha256').update(original).digest('hex');
const source=original.replace(/^import .*;\r?$/gm,'').replace(/^export /gm,'').replaceAll('import.meta.url','__moduleUrl');
const forbidden=()=>{throw new Error('INDEPENDENT_REVIEW_SIDE_EFFECT_FORBIDDEN');};
const execute=new Function('assert','createHash','readFileSync','mkdtempSync','mkdirSync','writeFileSync','rmSync','tmpdir','path','fileURLToPath','spawnSync','__moduleUrl','process',
 source+'\nreturn {checkerFailure,requireExpectedMutationFailure,outcomeCheck,valid};');
const functions=execute(assert,createHash,fs.readFileSync,forbidden,forbidden,forbidden,forbidden,tmpdir,path,fileURLToPath,forbidden,pathToFileURL(path.resolve(file)).href,process);
const contractError={failureClass:'CONTRACT_ASSERTION',errorName:'AssertionError',errorCode:'ERR_ASSERTION'};
const runtimeError={failureClass:'CHECKER_RUNTIME_ERROR',errorName:'TypeError',errorCode:null};
const diagnostic='canonical-field-set';
const id='independent-schema-review';
const resultFor=error=>({status:1,stdout:'',stderr:JSON.stringify(functions.checkerFailure(error))});
const observations=[];
const accepted=(name,error,expectedDiagnostic,expectedError)=>{
 const result=functions.requireExpectedMutationFailure(resultFor(error),id,expectedDiagnostic,expectedError);
 observations.push({name,accepted:true,failureClass:result.failureClass,errorName:result.errorName,diagnostic:result.diagnostic});
};
const rejected=(name,result,expectedDiagnostic=diagnostic,expectedError=contractError,wanted='MUTATION_UNEXPECTED_ERROR')=>{
 let error;try{functions.requireExpectedMutationFailure(result,id,expectedDiagnostic,expectedError);}catch(caught){error=caught;}
 assert.equal(error?.name,'MutationRunnerError',name);
 assert(error.diagnostic.startsWith(wanted+':'),name+':'+error?.diagnostic);
 observations.push({name,accepted:false,diagnostic:error.diagnostic});
};
let assertion;try{assert(false,diagnostic);}catch(error){assertion=error;}
accepted('explicit-contract-assertion-control',assertion,diagnostic,contractError);
for(const error of [new TypeError(diagnostic),new ReferenceError(diagnostic),new SyntaxError(diagnostic),new Error(diagnostic)]){
 rejected('same-diagnostic-'+error.name,resultFor(error));
}
let wrong;try{assert(false,diagnostic+':unrelated');}catch(error){wrong=error;}
rejected('same-prefix-different-diagnostic',resultFor(wrong),diagnostic,contractError,'MUTATION_WRONG_DIAGNOSTIC');
let implicit;try{assert(false);}catch(error){implicit=error;}
implicit.message=diagnostic;
rejected('generated-assertion-message-is-not-explicit-diagnostic',resultFor(implicit));
rejected('legacy-status-message-only-failure',{status:1,stdout:'',stderr:JSON.stringify({status:'FAIL',message:diagnostic})},diagnostic,contractError,'MUTATION_INVALID_FAILURE_REPORT');
rejected('multiple-json-failures',{status:1,stdout:'',stderr:resultFor(assertion).stderr+'\n'+resultFor(assertion).stderr},diagnostic,contractError,'MUTATION_INVALID_FAILURE_REPORT');
rejected('stdout-noise-with-correct-assertion',{...resultFor(assertion),stdout:'unexpected-output'},diagnostic,contractError,'MUTATION_MUST_FAIL');
rejected('zero-exit-with-correct-assertion',{...resultFor(assertion),status:0},diagnostic,contractError,'MUTATION_MUST_FAIL');
const runtimeDiagnostic='UNEXPECTED_FIXTURE_ERROR:null-cannot-delete-known:TypeError:INJECTED_NEGATIVE_FIXTURE_BUG';
accepted('dedicated-runtime-rejection-control',new TypeError(runtimeDiagnostic),runtimeDiagnostic,runtimeError);
rejected('dedicated-runtime-rejection-wrong-error-type',resultFor(new ReferenceError(runtimeDiagnostic)),runtimeDiagnostic,runtimeError);
const fixture=[];
functions.outcomeCheck(fixture,'explicit-contract-negative','FAIL',()=>functions.valid(['independent-contract-rejection']));
assert.equal(fixture[0].outcome,'FAIL');
let fixtureError;
try{functions.outcomeCheck([],'independent-runtime-negative','FAIL',()=>{throw new TypeError('synthetic');});}catch(error){fixtureError=error;}
assert.equal(fixtureError?.name,'TypeError');
assert.equal(fixtureError?.message,'UNEXPECTED_FIXTURE_ERROR:independent-runtime-negative:TypeError:synthetic');
observations.push({name:'negative-fixture-runtime-error-does-not-become-pass',accepted:false,diagnostic:fixtureError.message});
console.log(JSON.stringify({status:'PASS',scope:'IN_MEMORY_INDEPENDENT_SCHEMA_MUTATION_CLASSIFICATION_RECHECK',runtime:process.version,sourcePath:file,sourceHash,filesystemWrites:0,subprocesses:0,caseCount:observations.length,observations}));
